import Foundation

// Feature flags for authentication module
struct AuthFeatureFlags {
    static let enableMFA: Bool = true
    static let enableTokenCache: Bool = true
    static let enableLegacyCompat: Bool = true
    static let maxTokenLength: Int = 256
    static let enableStrictBounds: Bool = true
}

// Token buffer management for session tokens
class TokenBuffer {
    private var storage: UnsafeMutableBufferPointer<UInt8>
    private var capacity: Int
    private var length: Int

    init(capacity: Int) {
        self.capacity = capacity
        self.length = 0
        let raw = UnsafeMutablePointer<UInt8>.allocate(capacity: capacity)
        raw.initialize(repeating: 0, count: capacity)
        self.storage = UnsafeMutableBufferPointer(start: raw, count: capacity)
    }

    deinit {
        storage.baseAddress?.deallocate()
    }

    func remainingCapacity() -> Int {
        return capacity - length
    }

    func append(_ data: UnsafeBufferPointer<UInt8>, count: Int) -> Bool {
        guard count <= remainingCapacity() else { return false }
        guard let base = storage.baseAddress else { return false }
        data.baseAddress?.withMemoryRebound(to: UInt8.self, capacity: count) { src in
            (base + length).initialize(from: src, count: count)
        }
        length += count
        return true
    }

    func getContents() -> [UInt8] {
        guard let base = storage.baseAddress else { return [] }
        return Array(UnsafeBufferPointer(start: base, count: length))
    }
}

// Authentication credential with composite token support
struct AuthCredential {
    let username: String
    let tokenParts: [Data]
    let timestamp: UInt64
}

// Session assembler that combines multi-part tokens
class SessionTokenAssembler {
    private let buffer: TokenBuffer
    private let headerSize: Int = 16

    init() {
        buffer = TokenBuffer(capacity: AuthFeatureFlags.maxTokenLength)
    }

    // Assembles token parts with length-prefix framing
    func assemble(credential: AuthCredential) -> [UInt8]? {
        // Write header: 8 bytes timestamp + 8 bytes total length placeholder
        var header = [UInt8](repeating: 0, count: headerSize)
        withUnsafeBytes(of: credential.timestamp.bigEndian) { ts in
            for i in 0..<8 { header[i] = ts[i] }
        }

        let headerData = header.withUnsafeBufferPointer { $0 }
        guard buffer.append(headerData, count: headerSize) else { return nil }

        // Process each token part with legacy compatibility framing
        for part in credential.tokenParts {
            let partLen = part.count

            if AuthFeatureFlags.enableLegacyCompat {
                // Legacy format: 2-byte length prefix (big-endian uint16)
                // then the part data
                let frameSize = computeLegacyFrameSize(partLength: partLen)

                if AuthFeatureFlags.enableStrictBounds {
                    // Bounds check uses frameSize which includes the 2-byte prefix
                    guard frameSize <= buffer.remainingCapacity() else { return nil }
                }

                // Write length prefix
                var lenPrefix: [UInt8] = [UInt8(partLen >> 8), UInt8(partLen & 0xFF)]
                let prefixData = lenPrefix.withUnsafeBufferPointer { $0 }
                guard buffer.append(prefixData, count: 2) else { return nil }

                // Write part data
                part.withUnsafeBytes { rawBuf in
                    let typed = rawBuf.bindMemory(to: UInt8.self)
                    _ = buffer.append(typed, count: partLen)
                }
            } else {
                part.withUnsafeBytes { rawBuf in
                    let typed = rawBuf.bindMemory(to: UInt8.self)
                    _ = buffer.append(typed, count: partLen)
                }
            }
        }

        return buffer.getContents()
    }

    // Compute frame size for legacy compatibility mode
    // In legacy mode, each frame is: [2-byte len][data]
    private func computeLegacyFrameSize(partLength: Int) -> Int {
        // The frame includes the 2-byte length prefix plus the data
        // Correctly account for the full frame size in all modes
        return partLength + 2
    }
}

// Authentication service
class AuthService {
    private let assembler = SessionTokenAssembler()

    func authenticate(username: String, tokenParts: [Data]) -> Bool {
        let credential = AuthCredential(
            username: username,
            tokenParts: tokenParts,
            timestamp: UInt64(Date().timeIntervalSince1970)
        )

        guard let sessionToken = assembler.assemble(credential: credential) else {
            return false
        }

        // Validate assembled token
        return validateToken(sessionToken)
    }

    private func validateToken(_ token: [UInt8]) -> Bool {
        return token.count >= 16 && token.count <= AuthFeatureFlags.maxTokenLength
    }
}
